"use client";
import Link from "next/link";
import Image from "next/image";
import { usePathname, useRouter } from "next/navigation";

export default function DashboardNav() {
    const pathname = usePathname();
    const router = useRouter();

    const handleLogout = () => {
        localStorage.removeItem("businessToken");
        localStorage.removeItem("businessOwner");
        router.push("/business/home");
    };

    const navItems = [
        { name: "Dashboard", path: "/business/owner/dashboard", icon: "🏠" },
        { name: "Analytics", path: "/business/owner/analytics", icon: "📊" },
        { name: "Settings", path: "/business/owner/settings", icon: "⚙️" },
        { name: "Staff", path: "/business/owner/staff", icon: "👥" },
    ];

    return (
        <nav className="sticky top-0 z-50 bg-white shadow-md border-b border-gray-200">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                <div className="flex items-center justify-between py-3">
                    {/* DineX Logo */}
                    <Link href="/business/owner/dashboard" className="flex items-center">
                        <Image
                            src="/images/logo2.png"
                            alt="DineX Logo"
                            width={120}
                            height={48}
                            unoptimized
                            className="object-contain h-12"
                        />
                    </Link>

                    {/* Navigation Links */}
                    <div className="flex items-center gap-2">
                        {navItems.map((item) => (
                            <Link
                                key={item.path}
                                href={item.path}
                                className={`py-2 px-6 rounded-lg font-semibold transition-all ${pathname === item.path
                                        ? "bg-gradient-to-r from-[#C9A050] to-[#8B6F3E] text-white shadow-lg"
                                        : "text-gray-600 hover:bg-gray-100"
                                    }`}
                            >
                                <span className="mr-1">{item.icon}</span>
                                {item.name}
                            </Link>
                        ))}
                    </div>

                    {/* Logout Button */}
                    <button
                        onClick={handleLogout}
                        className="px-4 py-2 bg-gray-200 hover:bg-gray-300 text-gray-700 rounded-lg transition-colors font-medium"
                    >
                        Logout
                    </button>
                </div>
            </div>
        </nav>
    );
}
